def close(x, ref, rtol: float = 1e-12, atol: float = 1e-12) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def same(x, ref) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    for u, v in zip(a.flat, r.flat):
        if u != v:
            print('mismatch', u, v)
            return False
    return True

A = np.array([[1., 0., 2., 0.], [0., 0., 3., 0.], [4., 5., 0., 0.], [0., 0., 0., 6.]])
S = sp.csr_array(A)

@test
def test_dia():
    D = S.todia()
    assert D.format == "dia" and D.nnz == 14
    assert close(D.data, dia_data) and same(D.offsets, dia_off)
    assert "DIAgonal sparse array of dtype 'float64'" in repr(D) and "(5 diagonals)" in repr(D)
    assert close(D.toarray(), A) and close(D.tocsr().toarray(), A) and close(D.tocsc().toarray(), A)
    DT = D.T
    assert close(DT.data, dia_T_data) and same(DT.offsets, dia_T_off)
    D2 = sp.diags_array([np.array([1., 2., 3.]), np.array([4., 5.])], offsets=[0, -1])
    assert D2.format == "dia" and close(D2.data, diags_data) and same(D2.offsets, diags_off)
    DS = D + sp.dia_array(np.eye(4))
    assert DS.format == "dia" and close(DS.data, dia_add_data) and same(DS.offsets, dia_add_off)
    DM = D @ D
    assert DM.format == "dia" and close(DM.data, dia_mm_data) and same(DM.offsets, dia_mm_off)
    assert close(D @ np.array([1., 2., 3., 4.]), dia_mv)
    assert close(D @ np.eye(4), A)
    assert close(D.sum(axis=0), dia_sum0) and close(D.sum(axis=1), dia_sum1) and D.sum() == 21.0
    assert close(D.diagonal(1), [0., 3., 0.]) and close((D * 2.0).toarray(), 2 * A)
    E = sp.eye(3, 4, k=1)
    assert E.format == "dia" and close(E.data, eye_data) and same(E.offsets, eye_off)
    assert sp.isspmatrix_dia(sp.dia_matrix(A)) and not sp.isspmatrix_dia(D)
test_dia()

@test
def test_bsr():
    B = S.tobsr((2, 2))
    assert B.format == "bsr" and B.blocksize == (2, 2) and B.nnz == 16
    assert close(B.data, bsr_data) and same(B.indices, bsr_ind) and same(B.indptr, bsr_ptr)
    assert "blocksize=2x2" in repr(B)
    assert S.tobsr().blocksize == (1, 1)
    G = sp.csr_array(np.kron(np.eye(3), np.array([[1., 2.], [3., 4.]])) + np.diag(np.arange(1., 7.)))
    assert G.tobsr().blocksize == (2, 2)
    BT = B.T
    assert close(BT.data, bsr_T_data) and same(BT.indices, bsr_T_ind) and same(BT.indptr, bsr_T_ptr)
    BB = B @ B
    assert BB.format == "bsr" and close(BB.data, bsr_mm_data) and same(BB.indices, bsr_mm_ind) and same(BB.indptr, bsr_mm_ptr)
    BC = B @ S
    assert BC.blocksize == (2, 1) and close(BC.toarray(), bsr_csr_mm)
    assert close((B + B).data, bsr_add_data) and (B - B).nnz == 0
    assert close(B @ np.array([1., 2., 3., 4.]), bsr_mv)
    assert close(B @ np.arange(8.).reshape(4, 2), bsr_mm2)
    assert close(B.diagonal(1), bsr_diag1) and close(B.diagonal(-1), bsr_diagm1)
    Bc = B.tocsr()
    assert same(Bc.indices, bsr_csr_ind) and close(Bc.data, bsr_csr_data)
    assert close(B.toarray(), A) and close(B.tocoo().toarray(), A)
    B2 = sp.bsr_array((np.ones((2, 2, 2)), np.array([0, 1]), np.array([0, 1, 2])), shape=(4, 4))
    assert close(B2.toarray(), [[1., 1., 0., 0.], [1., 1., 0., 0.], [0., 0., 1., 1.], [0., 0., 1., 1.]])
    K = sp.kron(sp.csr_array(np.array([[1., 2.], [0., 3.]])), np.array([[0., 1.], [1., 0.]]))
    assert K.format == "bsr" and close(K.data, kron_data)
    assert sp.kron(sp.eye(2), sp.eye(2)).format == "bsr"
test_bsr()

@test
def test_lil():
    Li = S.tolil()
    Li[0, 1] = 7.
    Li[1:3, 2] = 9.
    Li[3, [0, 1]] = np.array([1., 2.])
    Li[2, 0] = 0.
    assert Li.rows == [[0, 1, 2], [2], [1, 2], [0, 1, 3]]
    assert Li.data == [[1.0, 7.0, 2.0], [9.0], [5.0, 9.0], [1.0, 2.0, 6.0]]
    assert Li[0, 1] == 7.0 and Li[-1, -1] == 6.0
    assert close(Li[[3, 0]].toarray(), lil_fancy)
    assert close(Li[1:4, 0:3].toarray(), lil_slice)
    Li2 = sp.lil_array((3, 3))
    Li2[:, 1] = 2.
    Li2[0, :] = np.array([1., 0., 3.])
    assert close(Li2.toarray(), lil2) and Li2.nnz == 4
    assert "List of Lists sparse array" in repr(Li2)
    assert close((Li @ np.ones(4)), Li.toarray() @ np.ones(4))
    assert close((Li * 2.0).toarray(), 2 * Li.toarray()) and (Li * 2.0).format == "lil"
    assert close(Li.T.toarray(), Li.toarray().T) and Li.T.format == "lil"
test_lil()

@test
def test_dok():
    Dk = sp.dok_array((3, 4))
    Dk[1, 2] = 5.
    Dk[0, 3] = 1.
    Dk[2, :] = 2.
    Dk[0, 3] = 0.
    assert close(Dk.toarray(), dok_d) and Dk.nnz == 5
    c = Dk.tocoo()
    assert same(c.row, dok_row) and same(c.col, dok_col)
    assert close(Dk @ np.array([1., 2., 3., 4.]), dok_mv)
    assert (1, 2) in Dk and Dk[1, 2] == 5.0 and Dk.get((0, 0)) == 0.0
    D2 = S.todok()
    assert close(D2.toarray(), A) and D2.format == "dok"
    assert close((D2 + S).toarray(), 2 * A) and (D2 + S).format == "dok"
    assert close(D2.T.toarray(), A.T)
    assert "Dictionary Of Keys sparse array" in repr(D2)
test_dok()

@test
def test_conversions():
    for X in (S.tocoo().todia().tobsr((2, 2)).tolil().todok().tocsc(), S.todok().tolil().todia().tocsr()):
        assert close(X.toarray(), A)
    assert S.asformat("dia").format == "dia" and S.asformat("bsr").format == "bsr"
    assert S.asformat("lil").format == "lil" and S.asformat("dok").format == "dok"
    assert sp.lil_matrix(A).tobsr((2, 2)).todia().tocoo().format == "coo"
    assert close(S.reshape((2, 8)).toarray(), reshape_d)
    assert close(S.reshape((8, 2), order='F').toarray(), reshapeF_d)
    assert close(S.tolil().reshape((2, 8)).toarray(), reshape_d)
    assert sp.diags([1., 2.]).format == "dia" and sp.eye(3).format == "dia"
    assert sp.eye(3, format="csr").format == "csr"
    assert sp.spdiags(np.ones((1, 3)), [0], 3, 3).format == "dia"
    assert sp.block_diag([sp.eye(2)]).format == "coo"
    assert sp.hstack([sp.csc_array(A), sp.csc_array(A)]).format == "csc"
    assert sp.hstack([S, S]).format == "csr"
    assert sp.vstack([sp.coo_array(A), sp.coo_array(A)]).format == "coo"
    assert sp.random(4, 4, density=0.5, format='dia', rng=1).format == "dia"
    assert close(sp.random(4, 5, density=0.5, format='lil', rng=2).toarray(), rand_lil)
test_conversions()

@test
def test_resize_setdiag():
    X1 = S.copy(); X1.resize((5, 3)); assert close(X1.toarray(), resize_csr)
    X2 = S.tocsc(); X2.resize((5, 3)); assert close(X2.toarray(), resize_csc)
    X3 = S.tocoo(); X3.resize((5, 3)); assert close(X3.toarray(), resize_coo)
    X4 = S.todia(); X4.resize((5, 3)); assert close(X4.toarray(), resize_dia)
    X5 = S.tobsr(); X5.resize((5, 3)); assert close(X5.toarray(), resize_bsr)
    X6 = S.tolil(); X6.resize((5, 3)); assert close(X6.toarray(), resize_lil)
    X7 = S.todok(); X7.resize((5, 3)); assert close(X7.toarray(), resize_dok)
    v = np.array([9., 8.])
    Y1 = S.copy(); Y1.setdiag(v, -1); assert close(Y1.toarray(), setdiag_csr)
    Y2 = S.tocsc(); Y2.setdiag(v, -1); assert close(Y2.toarray(), setdiag_csc)
    Y3 = S.tocoo(); Y3.setdiag(v, -1); assert close(Y3.toarray(), setdiag_coo)
    Y4 = S.todia(); Y4.setdiag(v, -1); assert close(Y4.toarray(), setdiag_dia)
    Y5 = S.tobsr(); Y5.setdiag(v, -1); assert close(Y5.toarray(), setdiag_csr)
    Y6 = S.tolil(); Y6.setdiag(v, -1); assert close(Y6.toarray(), setdiag_lil)
    Y7 = S.todok(); Y7.setdiag(v, -1); assert close(Y7.toarray(), setdiag_dok)
test_resize_setdiag()
